import sys
import math

def solve():
    def max_bit(n):
        if n == 0:
            return 0
        m = math.floor(math.log2(n))
        return m

    def merge(left, right):
        result = [0] * (len(left) + len(right))
        i = j = k = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                result[k] = left[i]
                i += 1
            else:
                result[k] = right[j]
                j += 1
            k += 1
        while i < len(left):
            result[k] = left[i]
            i += 1
            k += 1
        while j < len(right):
            result[k] = right[j]
            j += 1
            k += 1
        return result

    def sort(a):
        if len(a) <= 1:
            return a
        if len(a) == 2:
            if a[0] <= a[1]:
                return a
            else:
                return [a[1], a[0]]
        mid = len(a) // 2
        left = sort(a[:mid])
        right = sort(a[mid:])
        return merge(left, right)

    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        a = list(map(int, sys.stdin.readline().split()))
        b = [a[i] - (1 << max_bit(i + 1)) for i in range(n)]
        if sort(b) == sorted(b):
            print('YES')
        else:
            print('NO')

