from collections import defaultdict
import math

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        primes = defaultdict(int)
        max_num = max(arr)
        for num in arr:
            for prime in prime_factors(num):
                primes[prime] += 1
        if len([k for k in primes if primes[k] > n // 2]) > 0:
            print("-1")
            continue
        max_prime = 0
        for prime in primes:
            if prime > max_prime:
                max_prime = prime
        b = []
        c = []
