                return self.cache[(x, y)]
            self.cache[(x, y)] = 0
            if (x, y) == (x2, y2):
                return 0
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
