    while i < max_draws:
        if i % 2 == 0:
            output_draws[i] = (difference // 2 + 1, difference // 2)
        else:
            output_draws[i] = (difference // 2, difference // 2 + 1)
        i += 1
        j += 1

    result = []
    for i in range(n):
