                curr_y = max(curr_y, x)
                ans += abs(curr_x - x)
            ans *= 2
            curr_x, curr_y = 0, 0
            while points:
                _, y = heapq.heappop(points)
                if curr_y < y:
                    curr_y += 1
                elif curr_y > y:
                    curr_y -= 1
                curr_x = max(curr_x, y)
                ans += abs(curr_y - y)
